class PayrollProcessingService {
    private SalaryCalculationService salaryService;
    private TaxCalculationService taxService;
    private HRSystem hrSystem;
    private NotificationService notificationService;

    public PayrollProcessingService(SalaryCalculationService salaryService, TaxCalculationService taxService, 
                                  HRSystem hrSystem, NotificationService notificationService) {
        this.salaryService = salaryService;
        this.taxService = taxService;
        this.hrSystem = hrSystem;
        this.notificationService = notificationService;
    }

    public void processPayroll(Employee employee) {
        double monthlySalary = salaryService.calculateSalary(employee.getBaseSalary(), employee.getYearsOfService());
        double taxes = taxService.calculateTaxes(monthlySalary);
        double netPay = monthlySalary - taxes;

        System.out.println("Processing payroll for " + employee.getName());
        System.out.println("Gross Pay: $" + monthlySalary);
        System.out.println("Taxes: $" + taxes);
        System.out.println("Net Pay: $" + netPay);

        hrSystem.updateEmployeeRecord(employee.getEmployeeId(), "Payroll processed: $" + netPay);
        sendPayrollEmail(employee);
    }

    private void sendPayrollEmail(Employee employee) {
        if (employee.getEmail() != null) {
            notificationService.sendEmail(employee.getEmail(), "Your monthly payslip", "Please find your payslip attached.");
        }
    }
}

class VacationManagementService {
    private HRSystem hrSystem;
    private NotificationService notificationService;

    public VacationManagementService(HRSystem hrSystem, NotificationService notificationService) {
        this.hrSystem = hrSystem;
        this.notificationService = notificationService;
    }

    public boolean requestVacation(Employee employee, int days) {
        if (employee.getUsedVacationDays() + days <= employee.getVacationDays()) {
            employee.setUsedVacationDays(employee.getUsedVacationDays() + days);
            System.out.println("Vacation request approved for " + employee.getName() + ": " + days + " days");
            hrSystem.updateEmployeeRecord(employee.getEmployeeId(), "Vacation approved: " + days + " days");

            if (employee.getManager() != null) {
                notificationService.notifyManager(employee.getManager(), "Vacation request approved for " + employee.getName());
            }
            return true;
        } else {
            System.out.println("Vacation request denied for " + employee.getName() + ": insufficient days");
            return false;
        }
    }
}

