class AccountService {
    private SecurityService securityService;
    private NotificationService notificationService;

    public AccountService() {
        this.securityService = new SecurityService();
        this.notificationService = new NotificationService();
    }

    public void lockAccount(User user) {
        user.setActive(false);
        securityService.logSecurityEvent("ACCOUNT_LOCKED", "Account locked for user: " + user.getName());
        notificationService.sendAccountNotification(user, "Your account has been locked due to security reasons.");
    }

    public void unlockAccount(User user) {
        user.setActive(true);
        user.resetLoginAttempts();
        securityService.logSecurityEvent("ACCOUNT_UNLOCKED", "Account unlocked for user: " + user.getName());
        notificationService.sendAccountNotification(user, "Your account has been successfully unlocked.");
    }

    public void deleteAccount(User user, DatabaseService dbService) {
        securityService.logSecurityEvent("ACCOUNT_DELETION_STARTED", "User initiated account deletion");
        user.setActive(false);
        user.setEmail("[DELETED]");
        user.setPassword(null);
        user.clearLoginHistory();
        user.clearNotifications();
        dbService.deleteUser(user.getName());
        securityService.logSecurityEvent("ACCOUNT_DELETED", "Account deletion completed");
    }
}

class NotificationService {
