class ReportGenerationService {
    public String generateCompensationBreakdown(Employee employee, SalaryCalculationService salaryService, TaxCalculationService taxService) {
        double salary = salaryService.calculateBaseSalary(employee.getBaseSalary(), employee.getYearsOfService());
        double bonus = salaryService.calculatePerformanceBonus(employee.getBaseSalary(), employee.getPerformanceRating(), employee.getYearsOfService());
        double overtime = salaryService.calculateOvertimeCompensation(employee.getBaseSalary(), employee.getOvertimeHours());
        double gross = salary + bonus + overtime;
        double federalTax = taxService.calculateFederalTax(gross);
        double stateTax = taxService.calculateStateTax(gross);
        double ssTax = taxService.calculateSocialSecurityTax(gross);
        double totalTax = federalTax + stateTax + ssTax;
        double netPay = gross - totalTax;

        StringBuilder breakdown = new StringBuilder();
        breakdown.append("=== COMPENSATION BREAKDOWN ===\n");
        breakdown.append("Base Salary: $").append(String.format("%.2f", salary)).append("\n");
        breakdown.append("Performance Bonus: $").append(String.format("%.2f", bonus)).append("\n");
        breakdown.append("Overtime Pay: $").append(String.format("%.2f", overtime)).append("\n");
        breakdown.append("Gross Pay: $").append(String.format("%.2f", gross)).append("\n");
        breakdown.append("Federal Tax: $").append(String.format("%.2f", federalTax)).append("\n");
        breakdown.append("State Tax: $").append(String.format("%.2f", stateTax)).append("\n");
        breakdown.append("Social Security: $").append(String.format("%.2f", ssTax)).append("\n");
        breakdown.append("Net Pay: $").append(String.format("%.2f", netPay)).append("\n");
        return breakdown.toString();
    }

    public String generatePerformanceReviewReport(Employee employee) {
        StringBuilder report = new StringBuilder();
        report.append("=== ANNUAL PERFORMANCE REVIEW ===\n");
        report.append("Employee: ").append(employee.getName()).append(" (").append(employee.getEmployeeId()).append(")\n");
        report.append("Department: ").append(employee.getDepartment()).append("\n");
        report.append("Current Rating: ").append(employee.getPerformanceRating()).append("/5.0\n");
        report.append("Years of Service: ").append(employee.getYearsOfService()).append("\n");
        report.append("Certifications: ").append(employee.getSkillCertifications().size()).append("\n");

        if (employee.getPerformanceRating() >= 4.5) {
            report.append("Recommendation: Promotion candidate\n");
        } else if (employee.getPerformanceRating() < 2.5) {
            report.append("Recommendation: Performance improvement plan required\n");
        }

        return report.toString();
    }

    public void printPaySlip(Employee employee, SalaryCalculationService salaryService) {
        double salary = salaryService.calculateBaseSalary(employee.getBaseSalary(), employee.getYearsOfService());
        System.out.println("Pay slip for " + employee.getName() + ": $" + salary);
    }
}

