        this.emailService = new EmailNotificationService("smtp.company.com");
        this.complianceLogger = new ComplianceLogger("/var/logs/compliance.log");
        this.emailContentService = new EmailContentService();
    }

    public boolean requestVacationDays(Employee employee, int days) {
        if (employee.getUsedVacationDays() + days <= employee.getVacationDays()) {
            employee.setUsedVacationDays(employee.getUsedVacationDays() + days);

            hrDatabase.saveVacationRequest(employee.getEmployeeId(), days, true);

            String managerEmail = emailContentService.createManagerNotificationEmail(
                employee.getName(), employee.getEmployeeId(), days, 
                employee.getVacationDays() - employee.getUsedVacationDays(), employee.getDepartment());
            emailService.sendEmail(employee.getManager() + "@company.com", "Vacation Request - " + employee.getName(), managerEmail);

            logVacationActivity(employee.getEmployeeId(), days, "APPROVED");
            return true;
        } else {
            logVacationActivity(employee.getEmployeeId(), days, "DENIED");
            return false;
        }
    }

    private void logVacationActivity(String employeeId, int days, String status) {
        String logMessage = "Vacation request - Employee: " + employeeId + ", Days: " + days + ", Status: " + status;
        complianceLogger.logEvent("VACATION_REQUEST", logMessage);
    }
