class ISBNGenerationService {
    public String generateUniqueISBN(String genre) {
        long timestamp = System.currentTimeMillis();
        String category = genre != null && genre.equals("fiction") ? "FIC" : "NF";
        return "978-" + category + "-" + (timestamp % 100000) + "-" + String.format("%02d", (int)(Math.random() * 100));
    }
}

class PageCalculationService {
    public int calculateDynamicPageCount(String content, String format) {
        if (content != null) {
            int basePages = content.length() / 250;
            double formatMultiplier = format != null && format.equals("hardcover") ? 1.2 : 1.0;
            return Math.max(1, (int)(basePages * formatMultiplier));
        }
        return 1;
    }
}

class ValidationService {
    public boolean validateCompleteBookData(String title, String author, String isbn, double price, String content) {
        return title != null && !title.trim().isEmpty() && 
               author != null && !author.trim().isEmpty() && 
               validateISBNFormat(isbn) && 
               validatePriceRange(price) && 
               content != null && content.length() > 0;
    }

    public boolean validateISBNFormat(String isbn) {
        if (isbn == null) return false;
        String clean = isbn.replaceAll("[^0-9X]", "");
        return clean.length() == 10 || clean.length() == 13;
    }

    public boolean validatePriceRange(double price) {
        return price >= 0.99 && price <= 999.99;
    }

    public boolean validateRating(double rating) {
        return rating >= 1.0 && rating <= 5.0;
    }

    public boolean validateDiscountRate(double discountPercentage) {
        return discountPercentage >= 0.0 && discountPercentage <= 0.5;
    }
}

