        base_bonus = base_salary * 0.1
        if performance_rating >= 4.0:
            base_bonus *= 1.5
        elif performance_rating >= 3.5:
            base_bonus *= 1.2
        return base_bonus

    def calculate_annual_salary(self, base_salary: float, years_of_service: int, performance_rating: float) -> float:
        monthly_salary = self.calculate_salary(base_salary, years_of_service)
        bonus = self.calculate_bonus(base_salary, performance_rating)
        return monthly_salary * 12 + bonus

