    def log_transaction(self, type, details):
        print(f"[DB LOG] {type}: {details}")


class NotificationService:
    def __init__(self, api_key):
        self.api_key = api_key

    def send_email(self, recipient, subject, body):
        print(f"Sending email to: {recipient}, Subject: {subject}")


class Product:
    def __init__(self, name, price):
        self.name = name
        self.price = price
        self.product_id = f"PRD-{int(time.time() * 1000) % 100000}"
        self.customer_reviews = []
        self.average_rating = 0.0
        self.total_sales = 0
        self.stock_quantity = 100
        self.cost_price = price * 0.6
        self.database = InventoryDatabase("jdbc:mysql://localhost:3306/inventory")
        self.notification_service = NotificationService("API_KEY_12345")

    def apply_discount(self, percentage):
        return self.price * (1 - percentage / 100)

    def display_product(self):
        print(f"Product: {self.name}, Price: ${self.price}")

    def calculate_discounted_price(self, discount_percentage):
        discounted = self.price * (1 - discount_percentage / 100)
        self.database.log_transaction("DISCOUNT_APPLIED", f"Product: {self.product_id}, Discount: {discount_percentage}%")
        return discounted

    def calculate_profit_margin(self):
        return ((self.price - self.cost_price) / self.price) * 100

    def calculate_shipping_cost(self, destination):
        return 15.99 if destination.lower() == "international" else 5.99

