            self.database.log_transaction("REVIEW_ADDED", f"Product: {self.product_id}, Rating: {rating}")

    def process_sale(self, quantity, customer_email):
        if self.stock_quantity >= quantity:
            self.stock_quantity -= quantity
            self.total_sales += quantity
            self.database.update_stock(self.product_id, self.stock_quantity)
            self.notification_service.send_email(customer_email, "Purchase Confirmation", f"Receipt for {self.name}")
            if self.stock_quantity <= 10:
                self.notification_service.send_email("inventory@company.com", "Low Stock Alert", f"Product {self.name} low stock")
            self.database.log_transaction("SALE_COMPLETED", f"Product: {self.product_id}, Quantity: {quantity}")

    def restock_product(self, quantity, supplier_email):
