class SalaryCalculationService {
    fun calculateSalary(baseSalary: Double, yearsOfService: Int): Double {
        return baseSalary + (yearsOfService * 1000)
    }

    fun calculateBonus(baseSalary: Double, performanceRating: Double): Double {
        var baseBonus = baseSalary * 0.1
        when {
            performanceRating >= 4.0 -> baseBonus *= 1.5
            performanceRating >= 3.5 -> baseBonus *= 1.2
        }
        return baseBonus
    }

    fun calculateAnnualSalary(baseSalary: Double, yearsOfService: Int, performanceRating: Double): Double {
        val monthlySalary = calculateSalary(baseSalary, yearsOfService)
        val bonus = calculateBonus(baseSalary, performanceRating)
        return monthlySalary * 12 + bonus
    }
}

