class SalaryCalculationService {
    fun calculateBaseSalary(baseSalary: Double, yearsOfService: Int): Double {
        return baseSalary + (yearsOfService * 1000)
    }

    fun calculatePerformanceBonus(baseSalary: Double, performanceRating: Double, yearsOfService: Int): Double {
        val baseBonus = baseSalary * 0.12
        val ratingMultiplier = performanceRating / 5.0
        val serviceMultiplier = min(yearsOfService * 0.02, 0.15)
        return baseBonus * ratingMultiplier * (1.0 + serviceMultiplier)
    }

    fun calculateOvertimeCompensation(baseSalary: Double, overtimeHours: Double): Double {
        return if (overtimeHours > 0) {
            val hourlyRate = baseSalary / (52 * 40)
            overtimeHours * hourlyRate * 1.5
        } else {
            0.0
        }
    }

    fun calculateTotalCompensation(baseSalary: Double, yearsOfService: Int, performanceRating: Double, overtimeHours: Double): Double {
        val salary = calculateBaseSalary(baseSalary, yearsOfService)
        val bonus = calculatePerformanceBonus(baseSalary, performanceRating, yearsOfService)
        val overtime = calculateOvertimeCompensation(baseSalary, overtimeHours)
        return salary + bonus + overtime
    }
}

