    fun generateUniqueISBN(genre: String?): String {
        val timestamp = System.currentTimeMillis()
        val category = if (genre == "fiction") "FIC" else "NF"
        return "978-$category-${timestamp % 100000}-${String.format("%02d", Random.nextInt(100))}"
    }
}

class PageCalculationService {
    fun calculateDynamicPageCount(content: String?, format: String?): Int {
        return if (!content.isNullOrEmpty()) {
            val basePages = content.length / 250
            val formatMultiplier = if (format == "hardcover") 1.2 else 1.0
            max(1, (basePages * formatMultiplier).toInt())
        } else {
            1
        }
    }
}

class ValidationService {
    fun validateCompleteBookData(
        title: String?,
        author: String?,
        isbn: String?,
        price: Double,
        content: String?
    ): Boolean {
        return !title.isNullOrBlank() &&
               !author.isNullOrBlank() &&
               validateISBNFormat(isbn) &&
               validatePriceRange(price) &&
               !content.isNullOrEmpty()
    }

    fun validateISBNFormat(isbn: String?): Boolean {
        if (isbn.isNullOrEmpty()) return false
        val clean = isbn.replace("[^0-9X]".toRegex(), "")
        return clean.length == 10 || clean.length == 13
    }

    fun validatePriceRange(price: Double): Boolean {
        return price in 0.99..999.99
    }

    fun validateRating(rating: Double): Boolean {
        return rating in 1.0..5.0
    }

    fun validateDiscountRate(discountPercentage: Double): Boolean {
        return discountPercentage in 0.0..0.5
    }
}

