        review: String,
        rating: Double
    ) {
        val validator = ValidationService()
        if (validator.validateRating(rating)) {
            book.reviews.add(review)
            book.customerEmails.add(customerEmail)
            book.averageRating = recalculateRatingMetrics(
                book.averageRating,
                book.reviews.size,
                rating
            )
            sendReviewConfirmationEmail(book, customerEmail)
            logReviewActivity(book.isbn, customerEmail, rating)
        }
    }

    private fun recalculateRatingMetrics(
        currentAverage: Double,
        reviewCount: Int,
        newRating: Double
    ): Double {
        return if (reviewCount == 1) {
            newRating
        } else {
            (currentAverage * (reviewCount - 1) + newRating) / reviewCount
        }
    }

    private fun sendReviewConfirmationEmail(book: Book, customerEmail: String) {
