class PricingCalculationService {
    private val shippingService = ShippingService("FedEx")

    fun applyDiscount(price: Double, percentage: Double): Double {
        return price * (1 - percentage / 100)
    }

    fun calculateDynamicPricing(basePrice: Double, totalSales: Int, stockQuantity: Int, discountRate: Double): Double {
        val demandMultiplier = when {
            totalSales > 1000 -> 1.2
            totalSales > 500 -> 1.1
            else -> 1.0
        }
        val stockMultiplier = if (stockQuantity < 10) 1.15 else 1.0
        val seasonalMultiplier = if (java.time.LocalDate.now().monthValue == 12) 1.25 else 1.0
        return basePrice * demandMultiplier * stockMultiplier * seasonalMultiplier * (1 - discountRate)
    }

    fun calculateComplexProfitMargin(basePrice: Double, totalSales: Int, stockQuantity: Int, discountRate: Double, costPrice: Double, weight: Double): Double {
        val sellingPrice = calculateDynamicPricing(basePrice, totalSales, stockQuantity, discountRate)
        val shippingCost = shippingService.calculateShippingRate("domestic", weight)
        val totalCost = costPrice + shippingCost + (sellingPrice * 0.03)
        return ((sellingPrice - totalCost) / sellingPrice) * 100
    }

    fun calculateTieredDiscount(quantity: Int): Double {
        return when {
            quantity >= 100 -> 0.20
            quantity >= 50 -> 0.15
            quantity >= 10 -> 0.10
            quantity >= 5 -> 0.05
            else -> 0.0
        }
    }
}

