    }

    public class ISBNGenerationService : IISBNGenerationService
    {
        public string GenerateUniqueISBN(string genre)
        {
            long timestamp = DateTimeOffset.Now.ToUnixTimeMilliseconds();
            string category = (genre != null && genre.Equals("fiction")) ? "FIC" : "NF";
            Random random = new Random();
            return $"978-{category}-{timestamp % 100000}-{random.Next(100):D2}";
        }
