        {
            if (!string.IsNullOrEmpty(content))
            {
                int basePages = content.Length / 250;
                double formatMultiplier = (format != null && format.Equals("hardcover")) ? 1.2 : 1.0;
                return Math.Max(1, (int)(basePages * formatMultiplier));
