        {
            dbService = new DatabaseService("Server=localhost;Database=bookstore;Integrated Security=true;");
            emailService = new EmailService("smtp.bookstore.com");
            emailContentService = new EmailContentService();
            inventoryService = new InventoryManagementService();
        }

        public void ProcessSaleTransaction(Book book, string customerEmail)
        {
            book.TotalSales++;
            book.CustomerEmails.Add(customerEmail);

            inventoryService.UpdateInventoryStatus(book);

            dbService.UpdateSalesData(book.ISBN, book.TotalSales);

            string receiptEmail = emailContentService.GenerateSalesReceiptEmail(book);
            emailService.SendEmail(customerEmail, $"Purchase Confirmation - {book.Title}", receiptEmail);

            LogSalesTransaction(book, customerEmail);

            if (book.TotalSales % 100 == 0)
            {
                SendMilestoneNotification(book);
            }
