        private void LogSalesTransaction(Book book, string customerEmail)
        {
            var pricingService = new PricingService();
            double finalPrice = pricingService.CalculateFinalPrice(book.Price, book.DiscountRate);
            string logDetails = $"Sale completed - Book: {book.ISBN}, Customer: {customerEmail}, Price: ${finalPrice}";
            dbService.LogTransaction("SALE_COMPLETED", logDetails);
        }

        private void SendMilestoneNotification(Book book)
        {
            string subject = $"Sales Milestone Reached: {book.Title}";
            string body = $"Congratulations! '{book.Title}' has reached {book.TotalSales} sales!";
            emailService.SendEmail("sales@bookstore.com", subject, body);
        }
