    }

    public void ExecuteSmartRestock(Product product, string supplierEmail)
    {
        int recommendedStock = CalculateOptimalStockLevel(product.TotalSales);
        int restockQuantity = recommendedStock - product.StockQuantity;

        if (restockQuantity > 0)
        {
            product.StockQuantity += restockQuantity;
            database.UpdateStock(product.ProductId, product.StockQuantity);

            string restockEmail = emailContentService.GenerateSmartRestockEmail(product.Name, product.ProductId, restockQuantity, product.StockQuantity, recommendedStock, product.TotalSales);
            emailService.SendEmail(supplierEmail, $"Smart Restock Completed - {product.Name}", restockEmail);

            analytics.TrackEvent("SMART_RESTOCK", product.ProductId, new Dictionary<string, string> { ["quantity"] = restockQuantity.ToString() });
            database.LogTransaction("SMART_RESTOCK", $"Product: {product.ProductId}, Added: {restockQuantity}, Target: {recommendedStock}");
        }
    }

    private int CalculateOptimalStockLevel(int totalSales)
    {
        int averageMonthlySales = totalSales / Math.Max(1, DateTime.Now.Month);
        int seasonalFactor = DateTime.Now.Month == 12 ? 2 : 1;
        return averageMonthlySales * 2 * seasonalFactor;
    }
}

