        {
            case FoodType.BURGER: return 5.99;
            case FoodType.FRIES: return 2.49;
            case FoodType.PIZZA: return 7.99;
            case FoodType.DRINK: return 1.50;
            default: throw new ArgumentException("Unknown type");
        }
    }
