from enum import Enum
import random


class CharacterType(Enum):
    WARRIOR = 1
    MAGE = 2
    ARCHER = 3
    ROGUE = 4


class SkillType(Enum):
    BASIC = 1
    SPECIAL = 2
    SUPPORT = 3


class WeaponType(Enum):
    SWORD = 1
    STAFF = 2
    BOW = 3
    DAGGER = 4


class PetType(Enum):
    WOLF = 1
    FAIRY = 2
    HAWK = 3
    SHADOW_CAT = 4


class Stats:
    def __init__(self, hp, mp, atk, mag, def_, res, spd, crit):
        self.hp = hp
        self.mp = mp
        self.atk = atk
        self.mag = mag
        self.def_ = def_
        self.res = res
        self.spd = spd
        self.crit = crit

    def copy(self):
        return Stats(self.hp, self.mp, self.atk, self.mag, self.def_, self.res, self.spd, self.crit)


class Skill:
    def __init__(self, n, t, c):
        self.name = n
        self.type = t
        self.cost = c


class Weapon:
    def __init__(self, n, t, p):
        self.name = n
        self.type = t
        self.power = p


class Pet:
    def __init__(self, n, t, b):
        self.name = n
        self.type = t
        self.bond = b


class Enemy:
    def __init__(self, n, s):
        self.name = n
        self.stats = s


class GameCharacter:
    def __init__(self, n, t, lvl, s, k, w, p):
        self.name = n
        self.type = t
        self.level = lvl
        self.stats = s
        self.skills = k
        self.weapon = w
        self.pet = p


class PetBoostSystem:
    def offense_boost(self, c):
        if c.pet.type == PetType.WOLF:
            return int(c.stats.atk * min(0.25, 0.05 + c.pet.bond / 100.0))
        if c.pet.type == PetType.FAIRY:
            return int(c.stats.mag * min(0.25, 0.05 + c.pet.bond / 120.0))
        if c.pet.type == PetType.HAWK:
            return c.stats.spd // 3 + c.pet.bond // 6
        if c.pet.type == PetType.SHADOW_CAT:
            return 5 + c.pet.bond // 5
        return 0

    def defense_boost(self, c):
        if c.pet.type == PetType.WOLF:
            return c.stats.def_ // 6
        if c.pet.type == PetType.FAIRY:
            return c.stats.res // 4
        if c.pet.type == PetType.HAWK:
            return c.stats.spd // 6
        if c.pet.type == PetType.SHADOW_CAT:
            return 3
        return 0

    def pet_assist(self, c):
        if c.pet.type == PetType.WOLF:
            return random.randint(0, 99) < min(35, 10 + c.pet.bond // 3)
        if c.pet.type == PetType.FAIRY:
            return random.randint(0, 99) < min(40, 15 + c.pet.bond // 2)
        if c.pet.type == PetType.HAWK:
            return random.randint(0, 99) < min(30, 8 + c.pet.bond // 4)
        if c.pet.type == PetType.SHADOW_CAT:
            return random.randint(0, 99) < min(45, 12 + c.pet.bond // 2)
        return False

    def pet_assist_damage(self, c):
        if c.pet.type == PetType.WOLF:
            return 6 + c.pet.bond // 4
        if c.pet.type == PetType.FAIRY:
            return 4 + c.pet.bond // 5
        if c.pet.type == PetType.HAWK:
            return 5 + c.pet.bond // 6
        if c.pet.type == PetType.SHADOW_CAT:
            return 7 + c.pet.bond // 5
        return 0

    def pet_assist_heal(self, c):
        if c.pet.type == PetType.FAIRY:
            return 8 + c.pet.bond // 3
        return 0


class WeaponRuleSet:
    def apply_weapon(self, c, base):
        if c.weapon.type == WeaponType.SWORD:
            return base + c.weapon.power + c.stats.atk // 4
        if c.weapon.type == WeaponType.STAFF:
            return base + c.weapon.power // 2 + c.stats.mag // 2
        if c.weapon.type == WeaponType.BOW:
            return base + c.weapon.power + c.stats.spd // 3
        if c.weapon.type == WeaponType.DAGGER:
            return base + c.weapon.power + c.stats.spd // 2
        return base

    def crit_chance(self, c):
        if c.weapon.type == WeaponType.SWORD:
            return 8 + c.stats.crit
        if c.weapon.type == WeaponType.STAFF:
            return 5 + c.stats.crit // 2
        if c.weapon.type == WeaponType.BOW:
            return 15 + c.stats.crit
        if c.weapon.type == WeaponType.DAGGER:
            return 18 + c.stats.crit
        return 0


class DamageCalculator:
    def __init__(self):
        self.rng = random.Random()
        self.wr = WeaponRuleSet()
        self.pets = PetBoostSystem()

    def calc(self, c, s, e):
        base = 0
        if c.type == CharacterType.WARRIOR:
            base = int(c.stats.atk * (1.1 + c.level * 0.03)) - e.stats.def_ // 3
            if s.type == SkillType.SPECIAL:
                base += 12
        elif c.type == CharacterType.MAGE:
            base = c.stats.mag * 2 + (18 if s.type == SkillType.SPECIAL else 0) - e.stats.res // 2
        elif c.type == CharacterType.ARCHER:
            base = c.stats.atk + c.stats.spd // 2 + (10 if s.type == SkillType.SPECIAL else 0) - e.stats.def_ // 4
        elif c.type == CharacterType.ROGUE:
            base = c.stats.atk + c.stats.spd + (14 if s.type == SkillType.SPECIAL else 0) - e.stats.def_ // 5
        base = self.wr.apply_weapon(c, base)
        base += self.pets.offense_boost(c)
        if self.pets.pet_assist(c):
            base += self.pets.pet_assist_damage(c)
        critChance = self.wr.crit_chance(c) + (10 if c.type == CharacterType.ARCHER else 0)
        if self.rng.randint(0, 99) < critChance:
            base *= 2
        return max(0, base)


class HealCalculator:
    def __init__(self):
        self.pets = PetBoostSystem()

    def heal(self, c, s):
        amt = 0
        if c.type == CharacterType.WARRIOR:
