public class StreamProcessor extends DataProcessor {
    private DataReaderService readerService;
    private DataWriterService writerService;

    public StreamProcessor(String id, Map<String, Object> config, LoggingService loggingService,
                          DataReaderService readerService, DataWriterService writerService) {
        super(id, config, loggingService);
        this.readerService = readerService;
        this.writerService = writerService;
        this.supportedFormats.addAll(Arrays.asList("csv", "txt", "json", "xml"));
    }

    @Override
    public CompletableFuture<ProcessingResult> processData(DataInput input, ProcessingOptions options) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                isProcessing = true;
                validateInput(input);

                String content = readerService.readData(input.getFilePath());
                String[] lines = content.split("\n");
                StringBuilder processedContent = new StringBuilder();

                int lineCount = 0;
                for (String line : lines) {
                    String processed = processLine(line, options);
                    processedContent.append(processed).append("\n");
                    lineCount++;

                    if (lineCount % 1000 == 0) {
                        loggingService.logProgress("Processed " + lineCount + " lines");
                    }
                }

                writerService.writeData(options.getOutputPath(), processedContent.toString());

                return new ProcessingResult(lineCount, options.getOutputPath(), "SUCCESS");
            } catch (Exception e) {
                loggingService.logError("Processing error: " + e.getMessage());
                return new ProcessingResult(0, null, "ERROR: " + e.getMessage());
            } finally {
                isProcessing = false;
                cleanup();
            }
        });
    }

    private String processLine(String line, ProcessingOptions options) {
        if (options.shouldTransform()) {
            return line.toUpperCase().trim();
        }
        return line.trim();
    }

