        System.out.println("Initializing PayPal payment for " + customer.getName());

        if (validatePayPalPayment(amount, currency)) {
            String transactionId = generatePayPalTransactionId();
            logPayPalTransaction(transactionId, amount, currency, customer);
            return new PaymentResult(true, transactionId, "Payment processed successfully via PayPal");
        }
        return new PaymentResult(false, null, "PayPal payment validation failed");
    }

    private boolean validatePayPalPayment(double amount, String currency) {
        return amount > 0 && currency != null && !currency.isEmpty();
    }

    private String generatePayPalTransactionId() {
        return "PP_" + System.currentTimeMillis() + "_" + new Random().nextInt(10000);
    }

    private void logPayPalTransaction(String transactionId, double amount, String currency, CustomerInfo customer) {
        System.out.println("PayPal Transaction Log: " + transactionId + " - " + amount + " " + currency + " for " + customer.getEmail());
    }

    public boolean processRefund(String transactionId, double amount) {
        System.out.println("Processing PayPal refund for transaction: " + transactionId);
        return true;
    }
