class FileProcessor(private val outputDirectory: String, private val tempDirectory: String) {
    private val processingHistory = ConcurrentHashMap<String, String>()
    private val processingScope = CoroutineScope(Dispatchers.IO + SupervisorJob())

    init {
        ensureDirectoriesExist()
    }

    private fun ensureDirectoriesExist() {
