    }

    suspend fun processFilesAsync(fileNames: List<String>, options: ProcessingOptions): List<ProcessingResult> {
        return withContext(Dispatchers.IO) {
            fileNames.map { fileName ->
                async { processIndividualFile(fileName, options) }
            }.awaitAll()
        }
    }

    private suspend fun processIndividualFile(fileName: String, options: ProcessingOptions): ProcessingResult {
        return try {
            val content = withContext(Dispatchers.IO) { File(fileName).readText() }
            val checksum = calculateChecksum(content)

            if (processingHistory.containsKey(checksum)) {
                return ProcessingResult(fileName, "Skipped - Already processed", false)
            }

            var processed = applyTransformations(content, options)

            if (options.compress) {
                processed = compressContent(processed)
            }

            val outputFileName = generateOutputFileName(fileName, options)

            withContext(Dispatchers.IO) {
                File(outputFileName).writeText(processed)
            }

            if (options.createBackup) {
                createVersionedBackup(fileName)
            }

            if (options.validateOutput) {
                validateOutputFile(outputFileName)
            }

            processingHistory[checksum] = outputFileName
            updateProcessingLog(fileName, outputFileName)

            ProcessingResult(fileName, "Successfully processed", true)
        } catch (e: Exception) {
            ProcessingResult(fileName, "Error: ${e.message}", false)
        }
    }

    private fun applyTransformations(content: String, options: ProcessingOptions): String {
        var result = content

        if (options.toUpperCase) {
            result = result.uppercase()
        }

        if (options.removeEmptyLines) {
            result = result.lines().filter { it.trim().isNotEmpty() }.joinToString("\n")
        }

        if (options.addTimestamp) {
            result = "Processed at: ${Date()}\n$result"
        }

        return result
    }

    private fun compressContent(content: String): String {
        val outputStream = ByteArrayOutputStream()
        GZIPOutputStream(outputStream).use { gzip ->
            gzip.write(content.toByteArray())
        }
        return Base64.getEncoder().encodeToString(outputStream.toByteArray())
    }

    private fun calculateChecksum(content: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        return digest.digest(content.toByteArray()).joinToString("") { "%02x".format(it) }
    }

    private suspend fun createVersionedBackup(fileName: String) {
        val timestamp = System.currentTimeMillis()
        val backupFileName = "$tempDirectory/backups/${File(fileName).name}.$timestamp.backup"

