public class DefaultFileSystemOperations : IFileSystemOperations
{
    public async Task<string> ReadAllTextAsync(string fileName) => await File.ReadAllTextAsync(fileName);
    public async Task WriteAllTextAsync(string fileName, string content) => await File.WriteAllTextAsync(fileName, content);
    public async Task AppendAllTextAsync(string fileName, string content) => await File.AppendAllTextAsync(fileName, content);
    public void Copy(string source, string destination, bool overwrite) => File.Copy(source, destination, overwrite);
