        this.apiKey = apiKey;
        this.accountSid = accountSid;
        this.authToken = authToken;
        this.configuration = new HashMap<>();
        initializeConfiguration();
    }

    private void initializeConfiguration() {
        configuration.put("timeout", "30000");
        configuration.put("retries", "3");
        configuration.put("baseUrl", "https://api.twilio.com/2010-04-01");
    }

    public void sendSMS(String phoneNumber, String message) {
        authenticateWithTwilio();
        validatePhoneNumber(phoneNumber);
        System.out.println("Sending SMS via Twilio to " + phoneNumber + ": " + message);
    }

    public void sendBulkSMS(String[] phoneNumbers, String message) {
        ExecutorService executor = Executors.newFixedThreadPool(5);
        for (String number : phoneNumbers) {
            executor.submit(() -> sendSMS(number, message));
        }
        executor.shutdown();
    }

    public void sendScheduledSMS(String phoneNumber, String message, long delaySeconds) {
        Timer timer = new Timer();
        timer.schedule(new TimerTask() {
            @Override
            public void run() {
                sendSMS(phoneNumber, message);
            }
        }, delaySeconds * 1000);
    }

    private void authenticateWithTwilio() {
        System.out.println("Authenticating with Twilio API using SID: " + accountSid);
        System.out.println("Using auth token: " + authToken.substring(0, 5) + "...");
    }

    private void validatePhoneNumber(String phoneNumber) {
        if (!phoneNumber.matches("^\\+?[1-9]\\d{1,14}$")) {
            throw new IllegalArgumentException("Invalid phone number format");
        }
    }

    public void updateConfiguration(String key, String value) {
        configuration.put(key, value);
    }
}

